function infinityText() {
    gsap.registerPlugin(ScrollTrigger);

    const txtBanner = document.querySelector('.text_infinity-js');
    const txtContent = document.querySelectorAll('.text_infinity_text, .text_infinity_text_copy');

    if (txtBanner && txtContent.length) {
        const txtContentWidth = txtContent[0].offsetWidth;

        gsap.to(txtContent, {
            x: -txtContentWidth,
            ease: "linear",
            repeat: -1,
            duration: 25,
            modifiers: {
                x: gsap.utils.unitize(x => parseFloat(x) % -txtContentWidth) // boucle parfaite
            }
        });

        gsap.to(txtBanner, {
            scrollTrigger: {
                trigger: txtBanner,
                start: "top 80%",
                end: "10% 78%",
                scrub: .5
            },
            rotation: -2,
            ease: "ease"
        });
    }
}

function addClassOnScroll() {
  window.addEventListener('scroll', () => {
    if (window.scrollY > 0) {
      document.body.classList.add('scrolled');
    } else {
      document.body.classList.remove('scrolled');
    }
  });
}

function sliderTextMedia() {
    const sliders2 = document.querySelectorAll('.slider2');

    sliders2.forEach((slider2, index) => {
        // Cherche le slider1 correspondant, s'il existe
        const slider1 = document.querySelectorAll('.slider1')[index];

        const slides2Count = slider2.querySelectorAll('.splide__slide').length;
        const slides1Count = slider1 ? slider1.querySelectorAll('.splide__slide').length : 0;

        let main, secondary;

        // Initialisation slider1 si présent
        if (slider1) {
            main = new Splide(slider1, {
                type: 'loop',
                perPage: 1,
                arrows: false,
                pagination: false,
                autoplay: true,
                speed: 400,
            });
        }

        // Initialisation slider2
        secondary = new Splide(slider2, {
            type: 'loop',
            perPage: 1,
            arrows: slides2Count > 1,
            pagination: false,
            drag : slides2Count > 1,
            autoplay: true,
            speed: 400,
            gap: '29px'
        });

        // Synchronisation si slider1 existe
        if (main) main.sync(secondary);

        // Montage
        if (main) main.mount();
        secondary.mount();
    });
}

function sliderBanner1() {
    const sliderBanner1 = document.querySelectorAll('.banner_image_1-js');
    if(!sliderBanner1.length) return;

    sliderBanner1.forEach(sliderElement => {
        if (sliderElement) {
            const slides = sliderElement.querySelectorAll('.splide__slide');

            new Splide(sliderElement, {
                type: 'loop',
                perPage: 1,
                perMove: 1,
                arrows: slides.length > 1,
                draggable: slides.length > 1,
                pagination: false,
                speed: 300,
                autoplay: true,
            }).mount();
        }
    });
}

