function burgerMenu() {
    const burger = document.getElementById("burger");
    const overlay = document.getElementById("overlay-menu");
    const closeBtn = document.getElementById("close-btn");

    if (burger) {
        burger.addEventListener("click", () => {
            document.body.classList.toggle('menu-open');
            overlay?.classList.toggle("open");
        });
    }

    if (closeBtn) {
        closeBtn.addEventListener("click", () => {
            document.body.classList.remove('menu-open');
            overlay?.classList.remove("open");
        });
    }
}

function gravityCta() {
  let blocCta = document.querySelectorAll('.block-cta_link');
  if(!blocCta.length) return;

  blocCta.forEach(block => {
    const mascotte = block.querySelector('.mascotte');

    block.addEventListener('mousemove', (e) => {
      const rect = block.getBoundingClientRect();
      const centerX = rect.width / 2;
      const centerY = rect.height / 2;

      const x = e.clientX - rect.left - centerX;
      const y = e.clientY - rect.top - centerY;

      const r1 = Math.sqrt(x * x + y * y);
      const r2 = (1 - (r1 / centerX)) * r1;
      const angle = Math.atan2(y, x);

      const tx = Math.cos(angle) * r2 + e.clientX - rect.left;
      const ty = Math.sin(angle) * r2 + e.clientY - rect.top;

      const op = (r2 / r1) + 0.25;

      mascotte.style.setProperty('--tx', `${tx}px`);
      mascotte.style.setProperty('--ty', `${ty}px`);
      mascotte.style.setProperty('--opacity', op);
    });

    block.addEventListener('mouseleave', () => {
      mascotte.style.setProperty('--tx', `0px`);
      mascotte.style.setProperty('--ty', `0px`);
      mascotte.style.setProperty('--opacity', `0`);
    });
  });
}

function submenuOpen() {
    document.querySelectorAll(".main-nav li.menu-item-has-children").forEach(li => {
    const link = li.querySelector("a");
    const submenu = li.querySelector("ul.sub-menu");
    
    // Créer une flèche
    const arrow = document.createElement("button");
    arrow.classList.add("sub-menu-toggle");
    arrow.innerHTML = "▾";
    
    // Ajouter la flèche après le lien
    link.insertAdjacentElement("afterend", arrow);

    // Gestion du clic sur la flèche
    arrow.addEventListener("click", (e) => {
      e.preventDefault();
      link.classList.toggle("sub-menu-open");
    });

    // Gestion du survol du <li>
    [link, submenu].forEach(el => {
      if (!el) return; 
      el.addEventListener("mouseenter", () => {
        link.classList.add("sub-menu-open");
      });
    });

    [link, submenu].forEach(el => {
      if (!el) return; 
      el.addEventListener("mouseleave", () => {
        link.classList.remove("sub-menu-open");
      });
    });
  });
}

function debugAnchor() {
  document.querySelectorAll('a[href*="#"]').forEach(a => {
    a.addEventListener('click', e => {
        e.preventDefault();
        const targetId = a.getAttribute('href').split('#')[1];
        const target = document.getElementById(targetId);
        if (target) {
            target.scrollIntoView({ behavior: 'smooth' });
        }
        history.pushState(null, null, '#' + targetId); // met à jour l’URL sans recharger
    });

    if(window.location.hash) {
      const target = document.getElementById(window.location.hash.substring(1));
      if(target) {
          target.scrollIntoView({ behavior: 'smooth' });
      }
    }
  });
}

document.addEventListener('DOMContentLoaded', function() {
    infinityText();
    burgerMenu();
    sliderTextMedia();
    gravityCta();
    sliderBanner2();
    sliderBanner1();
    addClassOnScroll();
    submenuOpen();
    debugAnchor();
});